<?php
declare(strict_types=1);
namespace PkStore\Infrastructure\Database;
final class AffiliateInstaller {
    public static function run(): void {
        global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $cs=$wpdb->get_charset_collate();
        if ($wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}pkstore_affiliates (id INT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL,affiliate_code VARCHAR(20) NOT NULL,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,total_earned_pkr INT NOT NULL DEFAULT 0,total_paid_pkr INT NOT NULL DEFAULT 0,pending_pkr INT NOT NULL DEFAULT 0,payment_method VARCHAR(20) NOT NULL DEFAULT 'jazzcash',payment_account VARCHAR(100) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,PRIMARY KEY (id),UNIQUE INDEX idx_code (affiliate_code),UNIQUE INDEX idx_user (user_id),INDEX idx_status (status)) ENGINE=InnoDB {$cs};") === false) { throw new \\RuntimeException("Unable to create affiliate table."); }
        if ($wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}pkstore_affiliate_products (id INT UNSIGNED NOT NULL AUTO_INCREMENT,affiliate_id INT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,display_price_pkr INT NOT NULL DEFAULT 0,external_url VARCHAR(1000) NOT NULL,image_url VARCHAR(1000) NOT NULL DEFAULT '',platform VARCHAR(50) NOT NULL DEFAULT 'other',category VARCHAR(100) NOT NULL DEFAULT '',click_count INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,PRIMARY KEY (id),INDEX idx_affiliate (affiliate_id),INDEX idx_status (status)) ENGINE=InnoDB {$cs};") === false) { throw new \\RuntimeException("Unable to create affiliate table."); }
        if ($wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}pkstore_affiliate_commissions (id INT UNSIGNED NOT NULL AUTO_INCREMENT,affiliate_id INT UNSIGNED NOT NULL,order_id INT UNSIGNED NOT NULL,order_total_pkr INT NOT NULL,commission_pkr INT NOT NULL,rate_percent DECIMAL(5,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL,PRIMARY KEY (id),UNIQUE INDEX idx_order (order_id),INDEX idx_affiliate (affiliate_id,created_at)) ENGINE=InnoDB {$cs};") === false) { throw new \\RuntimeException("Unable to create affiliate table."); }
        if ($wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}pkstore_affiliate_payouts (id INT UNSIGNED NOT NULL AUTO_INCREMENT,affiliate_id INT UNSIGNED NOT NULL,amount_pkr INT NOT NULL,payment_method VARCHAR(20) NOT NULL,payment_account VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',transaction_id VARCHAR(100) DEFAULT NULL,created_at DATETIME NOT NULL,PRIMARY KEY (id),INDEX idx_affiliate (affiliate_id,created_at),INDEX idx_status (status)) ENGINE=InnoDB {$cs};") === false) { throw new \\RuntimeException("Unable to create affiliate table."); }
    }
}
